import { roundHalfEven } from '@acme/ledger';
export function total(lines: Line[] | null): number {
  if (lines === null) { return 0; }
  let sum = 0;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].qty > 0) { sum = sum + lines[i].qty * lines[i].unitCents; }
  }
  return roundHalfEven(sum);
}
